"Общий разговор Ловчих.":"Allgemeiner Plausch der Fänger.",
"Торговля: договаривайтесь о сделках — сами сделки идут через Аукцион.":"Handel: Macht Deals aus — abgewickelt wird über die Auktion.",
"Ищите команду для Разломов: пишите код комнаты и место.":"Sucht ein Team für Risse: Schreibt Raumcode und Ort.",
"Вопросы новичков и советы бывалых.":"Fragen von Neulingen, Tipps von Profis.",
