"ур. {0}":"Lv. {0}",
"Здесь пока тихо":"Hier ist es noch still",
"Напиши первым — тебя увидят все Ловчие твоего клана.":"Schreib als Erster — alle Fänger deines Clans sehen es.",
"Напиши первым — тебя увидят все Ловчие Ордена.":"Schreib als Erster — alle Fänger des Ordens sehen es.",
