"Это закрытый тестовый сервер. Введи ключ доступа — он сохранится только в этом браузере.":"Das ist ein geschlossener Testserver. Gib den Zugangsschlüssel ein — er wird nur in diesem Browser gespeichert.",
"Ключ доступа":"Zugangsschlüssel",
"Войти":"Einloggen",
