"Позвать друзей":"Freunde rufen",
"Ловчие":"Fänger",
"Твоя команда":"Dein Team",
"Изменить":"Ändern",
"Начать бой":"Kampf starten",
"Здоровье босса растёт с каждым Ловчим, награда — у каждого своя.":"Die Gesundheit des Bosses steigt mit jedem Fänger, die Belohnung bekommt jeder für sich.",
"Ждём, когда хозяин начнёт бой…":"Warte, bis der Gastgeber den Kampf startet…",
