"Европа":"Europa",
"Здесь сходятся старые дороги Нави, Олимпа, Асгарда и холмов сидов — от Москвы до Дублина.":"Hier treffen sich die alten Wege von Nav, Olymp, Asgard und den Hügeln der Sidhe — von Moskau bis Dublin.",
"Азия":"Asien",
"От Уральских гор до Тихого океана. Отсюда родом небесные драконы Китая, а Сибирь и Средняя Азия — края славянских духов.":"Vom Ural bis zum Pazifik. Von hier stammen die Himmelsdrachen Chinas, und Sibirien und Zentralasien sind Länder slawischer Geister.",
"Африка":"Afrika",
"Здесь, у Нила, стоят врата Дуата — родины египетских богов и духов пустыни.":"Hier am Nil stehen die Tore der Duat — der Heimat der ägyptischen Götter und Wüstengeister.",
"Северная Америка":"Nordamerika",
"Земля пернатых змеев: из долины Мехико вышли ацтекские боги и духи.":"Land der gefiederten Schlangen: Aus dem Tal von Mexiko kamen die aztekischen Götter und Geister.",
"Южная Америка":"Südamerika",
"Сельва, Анды и Амазонка. Ацтекские духи разлетелись и сюда — до самой Огненной Земли.":"Dschungel, Anden und Amazonas. Auch hierher flogen aztekische Geister — bis nach Feuerland.",
"Австралия и Океания":"Australien und Ozeanien",
"Своих мифологий у Ордена здесь пока нет: сюда забредают китайские духи из соседней Юго-Восточной Азии.":"Eigene Mythologien hat der Orden hier noch nicht: Chinesische Geister streifen aus dem benachbarten Südostasien herüber.",
"Антарктида":"Antarktis",
"Здесь только пингвины и ледяные духи. Врата сюда не открываются — слишком холодно даже для Ловчих.":"Hier gibt es nur Pinguine und Eisgeister. Die Tore öffnen sich nicht hierher — zu kalt, sogar für Fänger.",
"Миров духов всегда было много — у каждого народа свой: Навь у славян, царство Аида у греков, Асгард у скандинавов, холмы сидов у кельтов, Дуат у египтян, Небеса у китайцев, Миктлан у ацтеков. На местах их держал <b>Алатырь</b> — бел-горюч камень в середине всех миров. Каждые врата вели в свою землю, и духи не путали дорог.":"Geisterwelten gab es schon immer viele – jedes Volk hatte seine eigene: die Nav der Slawen, das Reich des Hades der Griechen, Asgard der Skandinavier, die Feenhügel der Kelten, die Duat der Ägypter, die Himmel der Chinesen, Mictlan der Azteken. An ihrem Platz hielt sie <b>Alatyr</b>, der weiße brennende Stein in der Mitte aller Welten. Jedes Tor führte in sein eigenes Land, und die Geister verwechselten nie ihre Wege.",
"Однажды осенней ночью Кощей Бессмертный решил спрятать свою смерть понадёжнее — прямо в сердце Алатыря. Камень треснул и раскололся. Все врата распахнулись разом, дороги между мирами спутались в клубок, и духи и боги семи мифологий высыпали в наш мир — каждый в своих краях. Эту ночь назвали <b>Перепутицей</b>. Кощей уверяет, что камень треснул сам, но Локи и Сунь Укун при этих словах почему-то хихикают.":"In einer Herbstnacht beschloss Koschei der Unsterbliche, seinen Tod sicherer zu verstecken – mitten im Herzen des Alatyr. Der Stein bekam einen Riss und zerbrach. Alle Tore sprangen auf einmal auf, die Wege zwischen den Welten verhedderten sich zu einem Knäuel, und die Geister und Götter von sieben Mythologien purzelten in unsere Welt – jeder in seine eigenen Lande. Diese Nacht nennt man <b>das Große Durcheinander</b>. Koschei beteuert, der Stein sei von selbst zersprungen, doch Loki und Sun Wukong kichern dabei seltsamerweise.",
"Теперь Гиппокамп плещется в фонтанах Рима, Леший гуляет по подмосковным паркам, а Ниссе греет котов в подъездах Осло: каждый дух живёт у себя на родине, и за чужими приходится шагать через Врата. Разломы — трещины от расколотого камня — открываются в каждом городе, а боги ставят святилища у себя на родине: Капища — на Руси, Храмы — в Греции, Пагоды — в Китае, Пирамиды — в Америке. Город рождает и своих, новых духов: Вайфайку, Трамвайника, Фонарника.":"Jetzt planscht ein Hippokamp in den Brunnen Roms, ein Leshy spaziert durch die Parks rund um Moskau, und ein Nisse wärmt Katzen in Treppenhäusern in Oslo: Jeder Geist lebt in seiner Heimat, und zu den anderen muss man durch die Tore treten. Risse – Spalten, die der zerbrochene Stein hinterließ – öffnen sich in jeder Stadt, und die Götter errichten ihre Heiligtümer in ihrer eigenen Heimat: Kapishches in der Rus, Tempel in Griechenland, Pagoden in China, Pyramiden in Amerika. Die Stadt bringt auch ihre eigenen, neuen Geister hervor: Vayfayka, Tramvaynik, Fonarnik.",
"Первыми с гостями поладили не учёные, а бабушки со своими оберегами: оказалось, оберег, сделанный с заботой, успокаивает любого духа, откуда бы тот ни был. Так появился <b>Орден Оберега</b> — союз Ловчих всех земель. Твоя задача — находить духов, ловить их оберегами, черпать силу из источников, закрывать разломы и собирать осколки Алатыря. Кто знает — может, однажды их хватит, чтобы распутать дороги домой.":"Als Erste kamen nicht Wissenschaftler mit den Neuankömmlingen zurecht, sondern Großmütter mit ihren Talismanen: Ein mit Liebe gemachter Talisman beruhigt jeden Geist, ganz gleich, woher er stammt. So entstand der <b>Orden des Talismans</b> – ein Bund von Fängern aus allen Ländern. Deine Aufgabe: Geister finden, sie mit Talismanen fangen, Kraft aus Quellen schöpfen, Risse schließen und Alatyr-Splitter sammeln. Wer weiß – vielleicht reichen sie eines Tages, um die Wege nach Hause zu entwirren.",
