"«Приходи, когда окрепнешь», — говорит {0}. Попробуй другую команду: смотри на стихии хранителя и береги щиты для его приёмов.":"„Komm wieder, wenn du stärker bist“, sagt {0}. Versuch ein anderes Team: Achte auf die Elemente des Hüters und spar deine Schilde für seine Attacken.",
"Хорошая тренировка! Награда за поединок с {0} сегодня уже получена.":"Gutes Training! Die heutige Belohnung für das Duell mit {0} hast du schon.",
"{0} жмёт тебе руку: «Честный бой!» Дружба крепнет.":"{0} schüttelt dir die Hand: „Fairer Kampf!“ Die Freundschaft wächst.",
