"Тапай — быстрая атака, она копит энергию; полная шкала — «Приём». Щиты берегут от приёмов соперника.":"Tippen ist ein schneller Angriff und lädt Energie; Leiste voll — „Spezial“. Schilde schützen vor den Attacken des Gegners.",
