"Соперник — Ловчий с рейтингом ±{0} от твоего, а если такого нет — Ловчий Ордена. Рейтинг зависит от силы соперника · опыт — за первые {1} боёв дня":"Dein Gegner ist ein Fänger mit einer Wertung von ±{0} zu deiner, und gibt es keinen, ein Fänger des Ordens. Die Wertung hängt von der Stärke des Gegners ab · EP für die ersten {1} Kämpfe des Tages",
