"Получено в этом сезоне":"In dieser Saison erhalten",
"Рейтинг зависит от соперника: победа над сильным даёт много, над слабым — мало; поражение от слабого стоит дороже. В твоей лиге победа над равным — +{0}, поражение — −{1}; чем выше лига, тем медленнее подъём. Из лиги можно выпасть. Награду за лигу дают один раз за сезон. В начале нового сезона рейтинг сверх {2} срезается наполовину, а за высшую лигу прошлого сезона Орден дарит сундук. В лигах «{3}», «{4}» и «{5}» — ещё и амулет.":"Die Wertung hängt vom Gegner ab: Ein Sieg über einen starken bringt viel, über einen schwachen wenig; eine Niederlage gegen einen schwachen kostet mehr. In deiner Liga bringt ein Sieg gegen einen Gleichstarken +{0}, eine Niederlage −{1}; je höher die Liga, desto langsamer geht es voran. Man kann aus einer Liga absteigen. Die Belohnung für eine Liga gibt es einmal pro Saison. Zu Beginn einer neuen Saison wird die Wertung über {2} halbiert, und für die höchste Liga der letzten Saison schenkt der Orden eine Truhe. In den Ligen „{3}“, „{4}“ und „{5}“ gibt es auch ein Amulett.",
"<b>{0}-е место</b> из {1} в сезоне":"<b>Platz {0}</b> von {1} in der Saison",
