" На этой неделе {0}.":" Diese Woche: {0}.",
"Цель растёт с числом участников. Награду ступени получает каждый, кто внёс нужное число очков.":"Das Ziel wächst mit der Teilnehmerzahl. Die Stufenbelohnung bekommt jeder, der genug Punkte beigetragen hat.",
