"Бои в реальном времени, рейтинг и лиги":"Echtzeitkämpfe, Wertung und Ligen",
"Клан своей мифологии — знамя над святилищами":"Ein Clan deiner Mythologie — sein Banner über den Heiligtümern",
"Продажа и покупка духов":"Geister kaufen und verkaufen",
"Шанс поимки ×1,5":"Fangchance ×1,5",
"Шанс поимки ×2":"Fangchance ×2",
