"Предел уровня духа +{0} за осколки Алатыря":"Levellimit des Geistes +{0} für Alatyr-Splitter",
"Вершина пути":"Gipfel des Pfads",
"Максимальный уровень Ловчего":"Maximales Fänger-Level",
"Сегодня получено {0} опыта — полностью до {1}":"Heute {0} EP erhalten — voll bis {1}",
"Сегодня получено {0} опыта — дальше вполовину до {1}":"Heute {0} EP erhalten — weiter zur Hälfte bis {1}",
"Сегодня получено {0} опыта — дальше на четверть":"Heute {0} EP erhalten — weiter zu einem Viertel",
"Опыт отдыха: следующие {0} опыта — вдвое":"Ruhe-EP: die nächsten {0} EP doppelt",
"За день опыт идёт полностью до {0}, дальше до {1} — вполовину, сверх — на четверть. Обучение и знаки Ордена дают опыт всегда полностью. За каждый день без игры копится опыт отдыха ({2}, не больше чем за {3} {4}): пока он есть, опыт вдвое.":"Am Tag gibt es EP voll bis {0}, danach bis {1} zur Hälfte, darüber zu einem Viertel. Tutorial und Abzeichen des Ordens geben EP immer voll. Für jeden Tag ohne Spiel sammeln sich Ruhe-EP ({2}, höchstens für {3} {4}): Solange sie da sind, gibt es doppelte EP.",
"Звание «{0}»":"Titel „{0}“",
"Ты здесь":"Du bist hier",
"Ты прошёл весь путь!":"Du hast den ganzen Pfad geschafft!",
"До {0} уровня — {1} опыта":"Bis Level {0}: {1} EP",
"дальше: {0} на {1}":"als Nächstes: {0} auf {1}",
"Опыт дают поимки, источники, разломы, капища и задания. С уровнем растут и твои духи: их можно усиливать до уровня Ловчего +5.":"EP gibt es für Fänge, Quellen, Risse, Kapishche und Quests. Mit deinem Level wachsen auch deine Geister: Du kannst sie bis Fänger-Level +5 verstärken.",
"С {0} уровня духов можно пробуждать: каждая звезда поднимает предел уровня духа ещё на {1}, до {2}.":"Ab Level {0} kannst du Geister erwecken: Jeder Stern hebt ihr Levellimit um weitere {1}, bis {2}.",
"Ищу настоящие места вокруг — Источники и Капища появятся через несколько секунд":"Suche echte Orte in der Nähe — Quellen und Kapishche erscheinen in ein paar Sekunden",
"Сервер мест не ответил":"Der Orte-Server hat nicht geantwortet",
"Посылка из Ордена":"Paket vom Orden",
"Поблизости пока нет ни одного Источника, поэтому Орден раз в день присылает припасы: {0}.":"In der Nähe gibt es noch keine Quelle, deshalb schickt dir der Orden einmal am Tag Vorräte: {0}.",
"Спасибо":"Danke",
"На проверке":"In Prüfung",
"Одобрено":"Angenommen",
"Отклонено":"Abgelehnt",
"Места":"Orte",
"Источники и Капища стоят у настоящих мест. Знаешь интересный объект рядом? Предложи его!":"Quellen und Kapishche stehen an echten Orten. Kennst du ein interessantes Objekt in der Nähe? Schlag es vor!",
"<b>Подходят:</b> памятники, скульптуры, фонтаны, мозаики, необычные здания, храмы, парки, источники, смотровые площадки.":"<b>Geeignet:</b> Denkmäler, Skulpturen, Springbrunnen, Mosaike, besondere Gebäude, Kirchen, Parks, Quellen, Aussichtspunkte.",
