"Перепутица спутала дороги мира, и Орден Оберега открыл Ловчим Врата: выбери в Атласе мира любой уголок Земли — там и начнёшь охоту. По карте ходи джойстиком, а в новые края шагай через Атлас. Настоящее местоположение телефона игре не нужно. Прогресс хранится на сервере игры и доступен только тебе; сервер проверяет каждое действие, поэтому нужен интернет. Места на карте и погода загружаются для выбранного района у OpenStreetMap и Open-Meteo (погоду можно выключить в настройках).":"Das Große Durcheinander hat die Wege der Welt verknotet, und der Orden des Talismans hat den Fängern die Tore geöffnet: Wähle im Weltatlas einen beliebigen Winkel der Erde — dort beginnt deine Jagd. Über die Karte läufst du mit dem Joystick, in neue Länder gelangst du über den Atlas. Den echten Standort deines Handys braucht das Spiel nicht. Dein Fortschritt liegt auf dem Spielserver und ist nur dir zugänglich; der Server prüft jede Aktion, deshalb brauchst du Internet. Orte auf der Karte und das Wetter für die gewählte Gegend kommen von OpenStreetMap und Open-Meteo (das Wetter lässt sich in den Einstellungen abschalten).",
"В путь":"Los geht’s",
"Уже играешь?":"Spielst du schon?",
