"Игра переехала на свой сервер в России — <b>duholov.ru</b>. Для этого вышло новое приложение: его нужно установить заново.":"Das Spiel ist auf einen eigenen Server in Russland umgezogen — <b>duholov.ru</b>. Dafür gibt es eine neue App, die du neu installieren musst.",
"Привяжи вход: Меню → Настройки → Учётная запись (Google, Яндекс, VK, Telegram или почта). Без этого прогресс гостя не перенесётся.":"Verknüpfe einen Login: Menü → Einstellungen → Konto (Google, Yandex, VK, Telegram oder E-Mail). Sonst wird der Gastfortschritt nicht übernommen.",
